ALTER POLICY "Leitura de papeis" ON public.user_roles USING (public.tms_active() AND (auth.uid()=user_id OR public.has_role(auth.uid(),'admin')));
ALTER POLICY "Leitura de modulos" ON public.user_modules USING (public.tms_active() AND (auth.uid()=user_id OR public.has_role(auth.uid(),'admin')));
ALTER POLICY "Leitura do proprio perfil" ON public.profiles USING (auth.uid()=id AND public.tms_active());
REVOKE EXECUTE ON FUNCTION public.tms_reliability_selftest() FROM authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.tms_records_commit(jsonb,text)'::regprocedure) INTO definition; definition:=replace(definition,'c:=x->>''collection''; rid:=x->>''id'';', 'c:=x->>''collection''; rid:=x->>''id''; IF c=''cteDocuments'' AND NOT public.tms_module(''/financeiro'') THEN RAISE EXCEPTION ''Use a importação fiscal validada de CT-e''; END IF;'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.tms_document_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.collection='cteDocuments' AND TG_OP='UPDATE' AND (NEW.data->>'chave' IS DISTINCT FROM OLD.data->>'chave' OR NEW.data->>'valorFiscal' IS DISTINCT FROM OLD.data->>'valorFiscal' OR NEW.data->>'xmlOriginal' IS DISTINCT FROM OLD.data->>'xmlOriginal') THEN RAISE EXCEPTION 'Documento fiscal original não pode ser alterado'; END IF; IF NEW.collection='orders' AND TG_OP='UPDATE' AND (NEW.data->>'chaveNFe' IS DISTINCT FROM OLD.data->>'chaveNFe' OR NEW.data->>'xmlOriginal' IS DISTINCT FROM OLD.data->>'xmlOriginal') THEN RAISE EXCEPTION 'XML e chave fiscal original não podem ser alterados'; END IF; RETURN NEW; END $$;
ALTER TABLE public.email_xml_inbox ADD COLUMN IF NOT EXISTS motivo_pendencia text;